      </Flex>
      {state.error && (
        <Alert
          type="error"
          showIcon
          title="暂时无法读取报表，请重试"
          action={<Button onClick={state.retry}>重试</Button>}
          style={{ marginBottom: 12 }}
        />
      )}
      <Spin spinning={state.busy} description={state.busy ? "正在更新" : undefined}>
